import{_ as o,o as r,c as i,aw as e}from"./chunks/framework.DLufY-ao.js";const a="data:image/png;base64,",p=JSON.parse('{"title":"Композиция","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/architecture/approaches/composition.md","filePath":"wiki/dev-commit/theory/architecture/approaches/composition.md"}'),l={name:"wiki/dev-commit/theory/architecture/approaches/composition.md"};function A(h,t,s,d,c,n){return r(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="композиция" tabindex="-1">Композиция <a class="header-anchor" href="#композиция" aria-label="Permalink to &quot;Композиция&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определения</p><ul><li><strong>Композиция и Агрегация</strong> - расширение функционала класса за счет &quot;внедрения&quot; других классов</li><li>Об агрегировании также часто говорят как об «отношении принадлежности» по принципу «у машины есть корпус, колёса и двигатель»</li><li><strong>Агрегация (агрегирование по ссылке)</strong> - отношение «часть-целое» между двумя равноправными объектами, когда один объект (контейнер) имеет ссылку на другой объект. Оба объекта могут существовать независимо: если контейнер будет уничтожен, то его содержимое - нет</li><li><strong>Композиция (агрегирование по значению)</strong> - более строгий вариант агрегирования, когда включаемый объект может существовать только как часть класса. Если класс будет уничтожен, то и включённый объект тоже будет уничтожен. Объект не может выйти за рамки своего класса. Объект будет создаваться внутри класса при создании класса и будет уничтожаться перед уничтожением родительского класса</li><li><strong>Функциональная композиция</strong> - передача результа вызова одной функции в качестве аргумента другой функции</li></ul></div><h2 id="агрегация-и-композиция" tabindex="-1">Агрегация и Композиция <a class="header-anchor" href="#агрегация-и-композиция" aria-label="Permalink to &quot;Агрегация и Композиция&quot;">​</a></h2><img src="'+a+'" style="width:400px;"><ul><li><em>Агрегация</em>: профессора - факультеты. Профессора остаются жить после разрушения факультета</li><li><em>Композиция</em>: университет - факультеты. Факультеты без университета уничтожаются</li></ul><h2 id="наследование-и-композиция" tabindex="-1">Наследование и композиция <a class="header-anchor" href="#наследование-и-композиция" aria-label="Permalink to &quot;Наследование и композиция&quot;">​</a></h2><ul><li><strong>Наследование</strong> - когда класс-наследник имеет все поля и методы родительского класса, и, как правило, добавляет какой-то новый функционал или/и поля</li><li>Наследование предполагает принадлежность к какой-то общности (похожесть). Наследуются атрибуты, т.е. возможности, другого класса, при этом объектов непосредственно родительского класса не создается</li><li>Минус наследования влияние родительского класса на дочерние</li></ul><hr><ul><li><strong>Ассоциация</strong> (частные случаи: Композиция и Агрегация) – когда один класс включает в себя другой класс в качестве одного из полей</li><li>Композиция предполагает формирование целого из частей. При композиции класс-агрегатор создает объекты других классов</li></ul>',10)])])}const D=o(l,[["render",A]]);export{p as __pageData,D as default};
